```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_delay",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration/1e6,0.5) p50_ms, quantile_cont(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby') OR (service_name='geo' AND span_name='geo.Geo/Nearby') GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), quantile_cont(duration/1e6,0.5), quantile_cont(duration/1e6,0.95) FROM normal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby') OR (service_name='geo' AND span_name='geo.Geo/Nearby') GROUP BY 1,2,3,4", "claim": "search's client span to geo.Geo/Nearby rose from p50 0.37ms to 1577ms, while geo's server span stayed at about 0.14ms."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration/1e6,0.5) p50_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), quantile_cont(duration/1e6,0.5) FROM normal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2,3,4", "claim": "search's other callee, rate, stayed at about 1.7ms p50, so the slowdown is specific to the search-to-geo connection."}
      ]
    }
  ],
  "propagation": [
    {"from": "geo", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration/1e6,0.5) p50_ms, quantile_cont(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') OR (service_name='search' AND span_name='geo.Geo/Nearby') GROUP BY 1,2,3,4", "claim": "search.Search/Nearby server p50 rose to about 1579ms, matching its slow geo.Geo/Nearby client call."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration/1e6,0.5) p50_ms, quantile_cont(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='frontend' AND span_name='search.Search/Nearby') GROUP BY 1,2,3,4", "claim": "User-facing frontend HTTP /hotels p50 rose from about 4.6ms to 1583ms, matching the slow search call."}]}
  ]
}
